    a.residual_spent_principal_atoms_total = bytemuck::pod_read_unaligned(&LIQ95_SHORT_RESIDUAL_SPENT_PRINCIPAL_ATOMS_TOTAL);
    a.residual_received_atoms_total = bytemuck::pod_read_unaligned(&LIQ95_SHORT_RESIDUAL_RECEIVED_ATOMS_TOTAL);
    a.funding_long_paid_atoms_total = bytemuck::pod_read_unaligned(&LIQ95_SHORT_FUNDING_LONG_PAID_ATOMS_TOTAL);
    a.funding_long_received_atoms_total = bytemuck::pod_read_unaligned(&LIQ95_SHORT_FUNDING_LONG_RECEIVED_ATOMS_TOTAL);
    a.funding_short_paid_atoms_total = bytemuck::pod_read_unaligned(&LIQ95_SHORT_FUNDING_SHORT_PAID_ATOMS_TOTAL);
    a.funding_short_received_atoms_total = bytemuck::pod_read_unaligned(&LIQ95_SHORT_FUNDING_SHORT_RECEIVED_ATOMS_TOTAL);
    a.fee_credits = bytemuck::pod_read_unaligned(&LIQ95_SHORT_FEE_CREDITS);
    a.cancel_deposit_escrow = bytemuck::pod_read_unaligned(&LIQ95_SHORT_CANCEL_DEPOSIT_ESCROW);
    a.last_fee_slot = bytemuck::pod_read_unaligned(&LIQ95_SHORT_LAST_FEE_SLOT);
    a.active_bitmap = bytemuck::pod_read_unaligned(&LIQ95_SHORT_ACTIVE_BITMAP);
    a.legs = bytemuck::pod_read_unaligned(&LIQ95_SHORT_LEGS);
    a.health_cert = bytemuck::pod_read_unaligned(&LIQ95_SHORT_HEALTH_CERT);
    a.stale_state = bytemuck::pod_read_unaligned(&LIQ95_SHORT_STALE_STATE);
    a.b_stale_state = bytemuck::pod_read_unaligned(&LIQ95_SHORT_B_STALE_STATE);
