    a.residual_received_atoms_total = bytemuck::pod_read_unaligned(&RES95_SHORT_RESIDUAL_RECEIVED_ATOMS_TOTAL);
    a.funding_long_paid_atoms_total = bytemuck::pod_read_unaligned(&RES95_SHORT_FUNDING_LONG_PAID_ATOMS_TOTAL);
