pub fn res105_short() -> PortfolioAccountV16Account {
    let mut a = PortfolioAccountV16Account::default();
    a.provenance_header = bytemuck::pod_read_unaligned(&RES105_SHORT_PROVENANCE_HEADER);
    a.owner = bytemuck::pod_read_unaligned(&RES105_SHORT_OWNER);
    a.capital = bytemuck::pod_read_unaligned(&RES105_SHORT_CAPITAL);
    a.pnl = bytemuck::pod_read_unaligned(&RES105_SHORT_PNL);
    a.reserved_pnl = bytemuck::pod_read_unaligned(&RES105_SHORT_RESERVED_PNL);
    a.residual_crystallized_loss_atoms_total = bytemuck::pod_read_unaligned(&RES105_SHORT_RESIDUAL_CRYSTALLIZED_LOSS_ATOMS_TOTAL);
    a.residual_spent_principal_atoms_total = bytemuck::pod_read_unaligned(&RES105_SHORT_RESIDUAL_SPENT_PRINCIPAL_ATOMS_TOTAL);
    a.residual_received_atoms_total = bytemuck::pod_read_unaligned(&RES105_SHORT_RESIDUAL_RECEIVED_ATOMS_TOTAL);
    a.funding_long_paid_atoms_total = bytemuck::pod_read_unaligned(&RES105_SHORT_FUNDING_LONG_PAID_ATOMS_TOTAL);
    a.funding_long_received_atoms_total = bytemuck::pod_read_unaligned(&RES105_SHORT_FUNDING_LONG_RECEIVED_ATOMS_TOTAL);
    a.funding_short_paid_atoms_total = bytemuck::pod_read_unaligned(&RES105_SHORT_FUNDING_SHORT_PAID_ATOMS_TOTAL);
    a.funding_short_received_atoms_total = bytemuck::pod_read_unaligned(&RES105_SHORT_FUNDING_SHORT_RECEIVED_ATOMS_TOTAL);
    a.fee_credits = bytemuck::pod_read_unaligned(&RES105_SHORT_FEE_CREDITS);
    a.cancel_deposit_escrow = bytemuck::pod_read_unaligned(&RES105_SHORT_CANCEL_DEPOSIT_ESCROW);
    a.last_fee_slot = bytemuck::pod_read_unaligned(&RES105_SHORT_LAST_FEE_SLOT);
    a.active_bitmap = bytemuck::pod_read_unaligned(&RES105_SHORT_ACTIVE_BITMAP);
    a.legs = bytemuck::pod_read_unaligned(&RES105_SHORT_LEGS);
    a.health_cert = bytemuck::pod_read_unaligned(&RES105_SHORT_HEALTH_CERT);
    a.stale_state = bytemuck::pod_read_unaligned(&RES105_SHORT_STALE_STATE);
    a.b_stale_state = bytemuck::pod_read_unaligned(&RES105_SHORT_B_STALE_STATE);
    a.rebalance_lock = bytemuck::pod_read_unaligned(&RES105_SHORT_REBALANCE_LOCK);
    a.liquidation_lock = bytemuck::pod_read_unaligned(&RES105_SHORT_LIQUIDATION_LOCK);
    a.close_progress = bytemuck::pod_read_unaligned(&RES105_SHORT_CLOSE_PROGRESS);
    a.resolved_payout_receipt = bytemuck::pod_read_unaligned(&RES105_SHORT_RESOLVED_PAYOUT_RECEIPT);
    a.loss_provenance = bytemuck::pod_read_unaligned(&RES105_SHORT_LOSS_PROVENANCE);
    a
}
